    "grammar": [
      {
        "title": "中国語の家族の言い方について",
        "html": "<p>家族を紹介するときは「我家有…口人」を使います。</p><div class=\"table-scroll\"><table><tr><td>爸爸</td><td>bàba</td><td>父</td></tr><tr><td>妈妈</td><td>māma</td><td>母</td></tr><tr><td>哥哥</td><td>gēge</td><td>兄</td></tr><tr><td>姐姐</td><td>jiějie</td><td>姉</td></tr><tr><td>弟弟</td><td>dìdi</td><td>弟</td></tr><tr><td>妹妹</td><td>mèimei</td><td>妹</td></tr></table></div>"
      },
      {
        "title": "年齢を尋ねる表現について",
        "html": "<p>⓵子どもに聞くとき</p><p data-audio=\"audio/clips/9f5885f960e2a9f5.mp3\">A： 你几岁了？Nǐjǐsuìle？</p><p>何歳なの。</p><p data-audio=\"audio/clips/4d8557e2e12ca236.mp3\">B： ５岁。Wǔsuì.</p><p>５歳。</p><p>⓶同年代の人に聞くとき</p><p data-audio=\"audio/clips/7047c46da3b9f299.mp3\">A： 你多大了？Nǐduōdàle？</p><p>いくつですか。</p><p data-audio=\"audio/clips/aa31763c0cc3b17f.mp3\">B： 25岁。Èrshíwǔsuì。</p><p>25歳。</p><p>⓷年配の人に聞くとき</p><p data-audio=\"audio/clips/c76fc2eab377fa88.mp3\">A： 您多大岁数了？Nínduōdàsuìshu le？</p><p>おいくつですか。</p><p data-audio=\"audio/clips/73ee0d0fee0d627f.mp3\">B： 76岁。Qīshíliùsuì。</p><p>76歳。</p>"
      }
    ],
